CREATE DATABASE IF NOT EXISTS career_copilot CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE career_copilot;

CREATE TABLE IF NOT EXISTS user (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255), auth_provider VARCHAR(20) NOT NULL DEFAULT 'email', google_picture VARCHAR(500), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS career_profile (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT UNIQUE NOT NULL, degree VARCHAR(160) DEFAULT '', college VARCHAR(200) DEFAULT '', graduation_year VARCHAR(4) DEFAULT '', target_role VARCHAR(160) DEFAULT '', skills JSON NOT NULL, completed BOOLEAN DEFAULT FALSE, FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS resume (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, filename VARCHAR(255) NOT NULL, extracted_text LONGTEXT NOT NULL, analysis JSON NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS job_analysis (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, resume_id INT, role VARCHAR(160) NOT NULL, description LONGTEXT NOT NULL, result JSON NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES user(id), FOREIGN KEY (resume_id) REFERENCES resume(id));
CREATE TABLE IF NOT EXISTS interview_result (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, role VARCHAR(160) NOT NULL, question TEXT NOT NULL, answer TEXT NOT NULL, score INT NOT NULL, feedback TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS career_roadmap (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, target_role VARCHAR(160) NOT NULL, experience_level VARCHAR(40) NOT NULL DEFAULT 'Beginner', education VARCHAR(200) DEFAULT '', hours_per_week INT NOT NULL DEFAULT 8, timeline VARCHAR(20) NOT NULL DEFAULT '6 months', readiness JSON NOT NULL, skill_analysis JSON NOT NULL, generated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS roadmap_phase (id INT PRIMARY KEY AUTO_INCREMENT, roadmap_id INT NOT NULL, position INT NOT NULL, title VARCHAR(160) NOT NULL, duration VARCHAR(80) NOT NULL, objective TEXT NOT NULL, skills JSON NOT NULL, topics JSON NOT NULL, practice_tasks JSON NOT NULL, recommended_project JSON NOT NULL, completion_criteria JSON NOT NULL, FOREIGN KEY (roadmap_id) REFERENCES career_roadmap(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS roadmap_task (id INT PRIMARY KEY AUTO_INCREMENT, phase_id INT NOT NULL, week INT NOT NULL DEFAULT 1, position INT NOT NULL, title VARCHAR(240) NOT NULL, description TEXT, estimated_minutes INT NOT NULL DEFAULT 30, completed BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (phase_id) REFERENCES roadmap_phase(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS roadmap_milestone (id INT PRIMARY KEY AUTO_INCREMENT, roadmap_id INT NOT NULL, position INT NOT NULL, title VARCHAR(160) NOT NULL, required_progress INT NOT NULL DEFAULT 0, completed BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (roadmap_id) REFERENCES career_roadmap(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS achievement (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, `key` VARCHAR(80) NOT NULL, title VARCHAR(160) NOT NULL, description VARCHAR(240) NOT NULL, unlocked BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_user_achievement (user_id, `key`), FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS github_analysis (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, username VARCHAR(120) NOT NULL, profile JSON NOT NULL, repositories JSON NOT NULL, analysis JSON NOT NULL, analyzed_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS job_application (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, company VARCHAR(180) NOT NULL, role VARCHAR(180) NOT NULL, location VARCHAR(180) DEFAULT '', package VARCHAR(120) DEFAULT '', application_date DATE, deadline DATE, description TEXT, notes TEXT, status VARCHAR(24) NOT NULL DEFAULT 'Saved', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_job_application_user_id (user_id), INDEX ix_job_application_status (status), FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS gd_result (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, topic VARCHAR(240) NOT NULL, position VARCHAR(8) NOT NULL, response LONGTEXT NOT NULL, score INT NOT NULL, evaluation JSON NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_gd_result_user_id (user_id), FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE IF NOT EXISTS skill_plan_task (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, skill VARCHAR(120) NOT NULL, day INT NOT NULL, title VARCHAR(240) NOT NULL, completed BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE KEY uq_user_skill_plan_day (user_id, skill, day), INDEX ix_skill_plan_task_user_id (user_id), FOREIGN KEY (user_id) REFERENCES user(id));
